import{_ as e,c as p,o as t,al as r}from"./chunks/framework.QMC68jD7.js";const h=JSON.parse('{"title":"什么是App打包","description":"","frontmatter":{},"headers":[],"relativePath":"tech/uniapp/4.App打包.md","filePath":"tech/uniapp/4.App打包.md","lastUpdated":1777271852000}'),i={name:"tech/uniapp/4.App打包.md"};function n(o,a,d,s,m,l){return t(),p("div",null,[...a[0]||(a[0]=[r('<h1 id="什么是app打包" tabindex="-1">什么是App打包 <a class="header-anchor" href="#什么是app打包" aria-label="Permalink to &quot;什么是App打包&quot;">​</a></h1><p>打包是将应用程序的源代码、资源文件、配置文件等打包成一个可执行的二进制文件的过程。打包后的应用程序可以被安装到手机上运行。</p><h1 id="了解安卓证书" tabindex="-1">了解安卓证书 <a class="header-anchor" href="#了解安卓证书" aria-label="Permalink to &quot;了解安卓证书&quot;">​</a></h1><p>安卓证书是一种数字证书，可以用于验证安卓设备中应用程序的真实性和作者身份。它基于公钥和私钥的加密算法，用于验证数字签名。同时，它还可以用于应用程序的加密和解密、数据传输加密和解密等方面。<br>安卓证书的主要构成部分包括：公钥和私钥、证书安装包、数字签名。<br></p><p>可通过线上工具生成安卓证书</p><p>1、安全性保证：Android平台建议使用数字证书对应用程序进行签名，以保证应用程序的安全性和可靠性，避免应用程序被篡改或者恶意攻击。<br>2、证书合法性：在签名应用程序时，需要进行证书合法性验证，以确保证书的真实性和合法性。<br>3、证书过期：证书具有一定的有效期限，因此需要定时的更新证书，并及时在开发者中心上注册新证书。</p><h1 id="打包" tabindex="-1">打包 <a class="header-anchor" href="#打包" aria-label="Permalink to &quot;打包&quot;">​</a></h1><p><img src="https://cdn.nlark.com/yuque/0/2023/png/8438658/1692713338434-9780ee63-04cb-4b51-b547-a3f3b8846d78.png#averageHue=%23f9f8f7&amp;clientId=uf6903fd5-8d79-4&amp;from=paste&amp;height=846&amp;id=u52daf541&amp;originHeight=1480&amp;originWidth=1294&amp;originalType=binary&amp;ratio=1.75&amp;rotation=0&amp;showTitle=false&amp;size=180392&amp;status=done&amp;style=none&amp;taskId=ub39b48f3-05b4-476b-96d0-21e9d3f37e1&amp;title=&amp;width=739.4285714285714" alt="image.png"></p>',8)])])}const _=e(i,[["render",n]]);export{h as __pageData,_ as default};
